<?php
namespace App\Filament\Resources\Roles;
use App\Filament\Resources\Concerns\AdminResource;use App\Filament\Resources\Roles\Pages\ManageRoles;use App\Models\Role;
use BackedEnum;use Filament\Actions\BulkActionGroup;use Filament\Actions\DeleteAction;use Filament\Actions\DeleteBulkAction;use Filament\Actions\EditAction;use Filament\Forms\Components\Select;use Filament\Forms\Components\TextInput;use Filament\Schemas\Schema;use Filament\Support\Icons\Heroicon;use Filament\Tables\Columns\IconColumn;use Filament\Tables\Columns\TextColumn;use Filament\Tables\Table;
class RoleResource extends AdminResource {protected static ?string $model=Role::class;protected static string $viewPermission='staff.manage';protected static ?string $managePermission='staff.manage';protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedKey;protected static ?string $navigationLabel='Vai trò & quyền';protected static string|\UnitEnum|null $navigationGroup='Hệ thống';protected static ?int $navigationSort=20;public static function form(Schema $s):Schema{return $s->components([TextInput::make('name')->label('Tên vai trò')->required(),TextInput::make('slug')->label('Mã')->required()->unique(ignoreRecord:true),Select::make('permissions')->relationship('permissions','name')->multiple()->preload()->searchable()->label('Quyền')])->columns(2);}public static function table(Table $t):Table{return $t->columns([TextColumn::make('name')->label('Vai trò')->searchable()->weight('bold'),TextColumn::make('slug')->label('Mã'),TextColumn::make('permissions_count')->counts('permissions')->label('Số quyền'),IconColumn::make('is_system')->label('Hệ thống')->boolean()])->recordActions([EditAction::make()->label('Sửa')->visible(fn(Role $r)=>!$r->is_system),DeleteAction::make()->label('Xóa')->visible(fn(Role $r)=>!$r->is_system)])->toolbarActions([BulkActionGroup::make([DeleteBulkAction::make()])]);}public static function canEdit(\Illuminate\Database\Eloquent\Model $r):bool{return parent::canEdit($r)&&!$r->is_system;}public static function canDelete(\Illuminate\Database\Eloquent\Model $r):bool{return parent::canDelete($r)&&!$r->is_system;}public static function getPages():array{return ['index'=>ManageRoles::route('/')];}}
